import { AnimatePresence, LazyMotion, domAnimation, m } from "motion/react";
import { Braces, Clock3, CornerDownLeft, Search, Trash2, X } from "lucide-react";
import { Fragment, useDeferredValue, useMemo, useState, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import { usePreferences } from "../hooks/usePreferences";
import { commandGroups, localizedText } from "../data/project";
import { fuzzySearchScore } from "../lib/search";

type CommandPaletteProps = {
  open: boolean;
  onClose: () => void;
};

type SearchResult = {
  label: string;
  detail: string;
  keywords: string;
  path: string;
  kind: "navigation" | "command";
};

const HISTORY_KEY = "hongyunx.atlas.search-history";

function readHistory() {
  try {
    const value = JSON.parse(localStorage.getItem(HISTORY_KEY) ?? "[]");
    return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string").slice(0, 6) : [];
  } catch {
    return [];
  }
}

function Highlight({ text, query }: { text: string; query: string }) {
  const needle = query.trim();
  if (!needle) return text;
  const index = text.toLowerCase().indexOf(needle.toLowerCase());
  if (index < 0) return <mark className="search-highlight search-highlight--fuzzy">{text}</mark>;
  return (
    <Fragment>
      {text.slice(0, index)}
      <mark className="search-highlight">{text.slice(index, index + needle.length)}</mark>
      {text.slice(index + needle.length)}
    </Fragment>
  );
}

const resultIcons: Record<SearchResult["kind"], typeof Search> = {
  navigation: CornerDownLeft,
  command: Braces,
};

export function CommandPalette({ open, onClose }: CommandPaletteProps) {
  const { t } = useTranslation();
  const { language, motionEnabled } = usePreferences();
  const [query, setQuery] = useState("");
  const [history, setHistory] = useState<string[]>(readHistory);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const deferredQuery = useDeferredValue(query);
  const navigate = useNavigate();

  const destinations = useMemo<SearchResult[]>(() => [
    { label: t("nav.overview"), path: "/docs", detail: t("overview.description"), keywords: "overview project 项目 总览", kind: "navigation" },
    { label: t("nav.commands"), path: "/docs/commands", detail: t("commandsPage.description", { count: 31 }), keywords: "CLI command flags 参数 命令", kind: "navigation" },
    { label: t("nav.gui"), path: "/docs/gui", detail: t("guiPage.description"), keywords: "GUI desktop Tauri chat editor workspace 桌面 对话 编辑器 工作区", kind: "navigation" },
  ], [t]);

  const searchIndex = useMemo<SearchResult[]>(() => {
    const commands = commandGroups.flatMap((group) => group.commands.map((command) => ({
      label: command.name,
      path: `/docs/commands?group=${group.id}`,
      detail: localizedText(command.summary, command.summaryEn, language),
      keywords: `${command.usage} ${command.examples.join(" ")} ${command.tags.join(" ")} ${command.summary} ${command.summaryEn ?? ""}`,
      kind: "command" as const,
    })));
    return [...destinations, ...commands];
  }, [destinations, language]);

  const results = useMemo(() => {
    const needle = deferredQuery.trim();
    if (!needle) return destinations;
    return searchIndex
      .map((item) => ({ item, score: fuzzySearchScore(`${item.label} ${item.detail} ${item.keywords}`, needle) }))
      .filter((result) => Number.isFinite(result.score))
      .sort((left, right) => left.score - right.score)
      .slice(0, 10)
      .map((result) => result.item);
  }, [deferredQuery, destinations, searchIndex]);

  const saveHistory = (value: string) => {
    const normalized = value.trim();
    if (!normalized) return;
    const next = [normalized, ...history.filter((item) => item !== normalized)].slice(0, 6);
    setHistory(next);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(next));
  };

  const go = (item: SearchResult) => {
    saveHistory(query);
    navigate(item.path);
    setQuery("");
    setSelectedIndex(0);
    onClose();
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setSelectedIndex((value) => Math.min(results.length - 1, value + 1));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setSelectedIndex((value) => Math.max(0, value - 1));
    } else if (event.key === "Enter" && results[selectedIndex]) {
      event.preventDefault();
      go(results[selectedIndex]);
    } else if (event.key === "Escape") {
      onClose();
    }
  };

  const status: ReactNode = query !== deferredQuery
    ? <><span className="status-spinner" />{t("palette.searching")}</>
    : <>{t("palette.results", { count: results.length })}</>;

  return (
    <LazyMotion features={domAnimation}>
      <AnimatePresence>
        {open ? (
          <m.div
            className="palette-backdrop"
            role="presentation"
            onMouseDown={onClose}
            initial={motionEnabled ? { opacity: 0 } : false}
            animate={{ opacity: 1 }}
            exit={motionEnabled ? { opacity: 0 } : undefined}
            transition={{ duration: 0.18 }}
          >
            <m.section
              className="command-palette"
              role="dialog"
              aria-modal="true"
              aria-label={t("palette.title")}
              onMouseDown={(event) => event.stopPropagation()}
              initial={motionEnabled ? { opacity: 0, y: -14, scale: 0.985 } : false}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={motionEnabled ? { opacity: 0, y: -8, scale: 0.99 } : undefined}
              transition={{ duration: 0.2, ease: "easeOut" }}
            >
              <header className="command-palette__heading">
                <div><span>GEO SEARCH</span><strong>{t("palette.title")}</strong><small>{t("palette.hint")}</small></div>
                <button className="icon-button" type="button" onClick={onClose} aria-label={t("common.close")} title={t("common.close")}><X size={17} /></button>
              </header>
              <div className="command-palette__search">
                <Search size={18} />
                <input autoFocus value={query} onChange={(event) => { setQuery(event.target.value); setSelectedIndex(0); }} onKeyDown={handleKeyDown} placeholder={t("common.searchPlaceholder")} aria-label={t("common.searchPlaceholder")} />
                {query ? <button className="clear-search" type="button" onClick={() => { setQuery(""); setSelectedIndex(0); }} aria-label={t("common.close")}><X size={14} /></button> : null}
              </div>
              {!query && history.length > 0 ? (
                <div className="search-history">
                  <div><span><Clock3 size={13} />{t("palette.history")}</span><button type="button" onClick={() => { setHistory([]); localStorage.removeItem(HISTORY_KEY); }}><Trash2 size={12} />{t("palette.clearHistory")}</button></div>
                  <div>{history.map((item) => <button type="button" key={item} onClick={() => { setQuery(item); setSelectedIndex(0); }}>{item}</button>)}</div>
                </div>
              ) : null}
              <div className="search-status" role="status" aria-live="polite">{status}</div>
              <div className="command-palette__results" role="listbox">
                {results.map((item, index) => {
                  const Icon = resultIcons[item.kind];
                  return (
                    <button type="button" role="option" aria-selected={index === selectedIndex} className={index === selectedIndex ? "selected" : ""} key={`${item.path}-${item.label}`} onMouseEnter={() => setSelectedIndex(index)} onClick={() => go(item)}>
                      <span className="palette-icon"><Icon size={15} /></span>
                      <span><b><Highlight text={item.label} query={deferredQuery} /></b><small><Highlight text={item.detail} query={deferredQuery} /></small></span>
                      <span className="result-kind">{t(`palette.${item.kind}`)}</span>
                    </button>
                  );
                })}
                {results.length === 0 ? <div className="palette-empty"><Search size={22} /><span>{t("common.noResults")}</span></div> : null}
              </div>
              <footer><span><kbd>↑</kbd><kbd>↓</kbd>{t("palette.select")}</span><span><kbd>Enter</kbd>{t("palette.open")}</span><span><kbd>Esc</kbd>{t("common.close")}</span></footer>
            </m.section>
          </m.div>
        ) : null}
      </AnimatePresence>
    </LazyMotion>
  );
}
